type ReportServiceTrendParams struct {
	Granularity     string             `json:"granularity"`
	Tz              string             `json:"tz"`
	BrandID         int64              `json:"brand_id"`
	OrgIds          []int64            `json:"org_ids"`
	CreatedByUserID pgtype.Int8        `json:"created_by_user_id"`
	RangeFrom       pgtype.Timestamptz `json:"range_from"`
	RangeTo         pgtype.Timestamptz `json:"range_to"`
}

type ReportServiceTrendRow struct {
	Series string      `json:"series"`
	Bucket pgtype.Date `json:"bucket"`
	Value  int64       `json:"value"`
}

// TEC-495 (F5-05f): /v1/reports aggregates (mobile reports and panel
// widgets). Scope arguments follow scopefilter like service_stats.sql:
// brand_id is always the domain brand of the active organization (K20),
// org_ids NULL = whole brand (brand / all scope) else the organizations in
// reach, created_by_user_id narrows own / assigned grants. Ranges are
// half open [range_from, range_to); buckets are date_trunc(granularity)
// of the timestamp in the caller's timezone, gaps are filled by the
// usecase.
func (q *Queries) ReportServiceTrend(ctx context.Context, arg ReportServiceTrendParams) ([]ReportServiceTrendRow, error) {
	rows, err := q.db.Query(ctx, reportServiceTrend,
		arg.Granularity,
		arg.Tz,
		arg.BrandID,
		arg.OrgIds,
		arg.CreatedByUserID,
		arg.RangeFrom,
		arg.RangeTo,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReportServiceTrendRow{}
	for rows.Next() {
		var i ReportServiceTrendRow
		if err := rows.Scan(&i.Series, &i.Bucket, &i.Value); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const reportStockTotals = `-- name: ReportStockTotals :one
SELECT
    COUNT(DISTINCT s.product_id) FILTER (WHERE s.quantity > 0 OR s.meters > 0)::bigint AS product_count,
    COALESCE(SUM(s.quantity), 0)::bigint AS quantity,
    COALESCE(SUM(s.meters), 0)::numeric(14,2)::float8 AS meters
FROM organization_product_stocks s
WHERE s.brand_id = $1
  AND ($2::bigint[] IS NULL OR s.organization_id = ANY ($2::bigint[]))
`

type ReportStockTotalsParams struct {
	BrandID int64   `json:"brand_id"`
	OrgIds  []int64 `json:"org_ids"`
}

type ReportStockTotalsRow struct {
	ProductCount int64   `json:"product_count"`
	Quantity     int64   `json:"quantity"`
	Meters       float64 `json:"meters"`
}

func (q *Queries) ReportStockTotals(ctx context.Context, arg ReportStockTotalsParams) (ReportStockTotalsRow, error) {
	row := q.db.QueryRow(ctx, reportStockTotals, arg.BrandID, arg.OrgIds)
	var i ReportStockTotalsRow
	err := row.Scan(&i.ProductCount, &i.Quantity, &i.Meters)
	return i, err
}

