const reportTopDealersByWarranty = `-- name: ReportTopDealersByWarranty :many
SELECT o.uuid AS organization_uuid, o.name AS organization_name, o.city,
       COUNT(*)::bigint AS warranty_count,
       COUNT(*) FILTER (WHERE w.status = 'active')::bigint AS active_count
FROM warranties w
JOIN organizations o ON o.id = w.organization_id
WHERE w.brand_id = $1
  AND o.type = 'dealer'
  AND o.deleted_at IS NULL
  AND ($2::bigint[] IS NULL OR w.organization_id = ANY ($2::bigint[]))
  AND w.start_at >= $3::timestamptz
  AND w.start_at < $4::timestamptz
GROUP BY o.id, o.uuid, o.name, o.city
ORDER BY warranty_count DESC, lower(o.name), o.id
LIMIT $5
`

type ReportTopDealersByWarrantyParams struct {
	BrandID   int64              `json:"brand_id"`
	OrgIds    []int64            `json:"org_ids"`
	RangeFrom pgtype.Timestamptz `json:"range_from"`
	RangeTo   pgtype.Timestamptz `json:"range_to"`
	RowLimit  int32              `json:"row_limit"`
}

type ReportTopDealersByWarrantyRow struct {
	OrganizationUuid uuid.UUID `json:"organization_uuid"`
	OrganizationName string    `json:"organization_name"`
	City             string    `json:"city"`
	WarrantyCount    int64     `json:"warranty_count"`
	ActiveCount      int64     `json:"active_count"`
}

func (q *Queries) ReportTopDealersByWarranty(ctx context.Context, arg ReportTopDealersByWarrantyParams) ([]ReportTopDealersByWarrantyRow, error) {
	rows, err := q.db.Query(ctx, reportTopDealersByWarranty,
		arg.BrandID,
		arg.OrgIds,
		arg.RangeFrom,
		arg.RangeTo,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReportTopDealersByWarrantyRow{}
	for rows.Next() {
		var i ReportTopDealersByWarrantyRow
		if err := rows.Scan(
			&i.OrganizationUuid,
			&i.OrganizationName,
			&i.City,
			&i.WarrantyCount,
			&i.ActiveCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const reportWarrantyCounts = `-- name: ReportWarrantyCounts :one

SELECT
    COUNT(*) FILTER (WHERE w.status = 'active')::bigint AS active_count,
    COUNT(*) FILTER (WHERE w.status = 'expired')::bigint AS expired_count,
    COUNT(*) FILTER (WHERE w.status = 'void')::bigint AS void_count,
    COUNT(*) FILTER (WHERE w.status = 'active'
                       AND w.end_at >= $1::timestamptz
                       AND w.end_at < $1::timestamptz + interval '30 days')::bigint AS expiring_count,
    COUNT(*) FILTER (WHERE w.start_at >= $2::timestamptz
                       AND w.start_at < $3::timestamptz)::bigint AS started_count
FROM warranties w
WHERE w.brand_id = $4
  AND ($5::bigint[] IS NULL OR w.organization_id = ANY ($5::bigint[]))
  AND ($6::bigint IS NULL OR EXISTS (
        SELECT 1 FROM services s WHERE s.id = w.service_id AND s.created_by_user_id = $6))
`

type ReportWarrantyCountsParams struct {
	NowAt           pgtype.Timestamptz `json:"now_at"`
	RangeFrom       pgtype.Timestamptz `json:"range_from"`
	RangeTo         pgtype.Timestamptz `json:"range_to"`
	BrandID         int64              `json:"brand_id"`
	OrgIds          []int64            `json:"org_ids"`
	CreatedByUserID pgtype.Int8        `json:"created_by_user_id"`
}

type ReportWarrantyCountsRow struct {
	ActiveCount   int64 `json:"active_count"`
	ExpiredCount  int64 `json:"expired_count"`
	VoidCount     int64 `json:"void_count"`
	ExpiringCount int64 `json:"expiring_count"`
	StartedCount  int64 `json:"started_count"`
}

// Warranties: own / assigned grants reach the warranties of their own
// services.
func (q *Queries) ReportWarrantyCounts(ctx context.Context, arg ReportWarrantyCountsParams) (ReportWarrantyCountsRow, error) {
	row := q.db.QueryRow(ctx, reportWarrantyCounts,
		arg.NowAt,
		arg.RangeFrom,
		arg.RangeTo,
		arg.BrandID,
		arg.OrgIds,
		arg.CreatedByUserID,
	)
	var i ReportWarrantyCountsRow
	err := row.Scan(
		&i.ActiveCount,
		&i.ExpiredCount,
		&i.VoidCount,
		&i.ExpiringCount,
		&i.StartedCount,
	)
	return i, err
}

