const upsertReportLayout = `-- name: UpsertReportLayout :one
INSERT INTO report_layouts (user_id, organization_id, brand_id, version, widgets)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (user_id, organization_id) DO UPDATE
SET version = EXCLUDED.version, widgets = EXCLUDED.widgets, brand_id = EXCLUDED.brand_id, updated_at = NOW()
RETURNING id, user_id, organization_id, brand_id, version, widgets, created_at, updated_at
`

type UpsertReportLayoutParams struct {
	UserID         int64  `json:"user_id"`
	OrganizationID int64  `json:"organization_id"`
	BrandID        int64  `json:"brand_id"`
	Version        int32  `json:"version"`
	Widgets        []byte `json:"widgets"`
}

func (q *Queries) UpsertReportLayout(ctx context.Context, arg UpsertReportLayoutParams) (ReportLayout, error) {
	row := q.db.QueryRow(ctx, upsertReportLayout,
		arg.UserID,
		arg.OrganizationID,
		arg.BrandID,
		arg.Version,
		arg.Widgets,
	)
	var i ReportLayout
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.OrganizationID,
		&i.BrandID,
		&i.Version,
		&i.Widgets,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
